const [statuses, standards] = await Promise.all([
  fetch('https://kfcain.github.io/nist-cmvp-api/api/indexes/statuses.json').then((r) => r.json()),
  fetch('https://kfcain.github.io/nist-cmvp-api/api/indexes/standards.json').then((r) => r.json()),
]);
const active = new Set((statuses.keys.Active ?? []).map((cert) => cert.certificate_number));
const active1403 = (standards.keys['FIPS 140-3'] ?? []).filter((cert) => active.has(cert.certificate_number));
console.log(active1403.slice(0, 10));
